Box map
A box map is an augmented quartile map with extra lower/upper outlier classes.

ggplot(data = NGA_wp, aes(x = "", y = wp_nonfunctional)) +
  geom_boxplot()









boxbreaks &lt;- function(v, mult = 1.5) {
  qv &lt;- unname(quantile(v))
  iqr &lt;- qv[4] - qv[2]
  upfence &lt;- qv[4] + mult * iqr
  lofence &lt;- qv[2] - mult * iqr
  bb &lt;- vector(mode = "numeric", length = 7)
  if (lofence &lt; qv[1]) {
    bb[1] &lt;- lofence
    bb[2] &lt;- floor(qv[1])
  } else {
    bb[2] &lt;- lofence
    bb[1] &lt;- qv[1]
  }
  if (upfence &gt; qv[5]) {
    bb[7] &lt;- upfence
    bb[6] &lt;- ceiling(qv[5])
  } else {
    bb[6] &lt;- upfence
    bb[7] &lt;- qv[5]
  }
  bb[3:5] &lt;- qv[2:4]
  return(bb)
}

boxmap &lt;- function(vnam, df, legtitle = NA, mtitle = "Box Map", mult = 1.5) {
  var &lt;- get.var(vnam, df)
  bb &lt;- boxbreaks(var)
  tm_shape(df) +
    tm_polygons() +
    tm_shape(df) +
    tm_fill(vnam, title = legtitle, breaks = bb, palette = "Blues",
            labels = c("lower outlier", "&lt; 25%", "25% - 50%",
                       "50% - 75%", "&gt; 75%", "upper outlier")) +
    tm_borders() +
    tm_title(mtitle) +
    tm_layout(legend.outside = TRUE)
}

tmap_mode("plot")
boxmap("wp_nonfunctional", NGA_wp)

A raw-breaks helper to complete the function family
The boxbreaks function handles quartiles, so I add a small rawbreaks companion that builds equal-count (quantile) breaks for any n, making the function family self-contained.

rawbreaks &lt;- function(v, n = 6) {
  unname(quantile(v, probs = seq(0, 1, length.out = n + 1)))
}

ratemap &lt;- function(vnam, df, n = 6, mtitle = "Rate Map") {
  var &lt;- get.var(vnam, df)
  bb &lt;- rawbreaks(var, n)
  tm_shape(df) +
    tm_fill(vnam, breaks = bb, palette = "Blues") +
    tm_borders(lwd = 0.1, alpha = 0.6) +
    tm_title(mtitle, size = 0.9) +
    tm_layout(legend.outside = TRUE)
}

ratemap("pct_functional", NGA_wp, n = 6, mtitle = "Functional rate (quantile breaks)")

Methodology and Data
Core question: which insurance stereotypes are real, and which are myths?
The strategic objectives are to:

maximise overall portfolio profitability;
maximise retention and loyalty among low-risk, highly profitable customers;
identify high-risk segments for appropriately calibrated premium pricing.

The analysis answers 10 research questions covering:

conventional and demographic factors;
brand-and-status factors;
behavioural and claim-history factors;
loyalty and policy-status factors;
geographic frequency and severity differences.

6.2 Explore the crisis-day network
Click an agent button to isolate its ego-network. The senior side-huddle clique becomes the visible core; interns and the Judge remain peripheral.


Network data prep
# crisis-day nodes (size = messages sent) on the same circular layout as Fig 6
net_nodes &lt;- tibble(agent_id = agent_levels) |&gt;
  left_join(messages |&gt; filter(phase == "crisis") |&gt; count(agent_id, name = "sent"), by = "agent_id") |&gt;
  mutate(sent = coalesce(sent, 0L), id = agent_id, label = node_lab[agent_id],
         ang = pi/2 + 2*pi*(match(agent_id, agent_levels) - 1) / length(agent_levels),
         x = cos(ang), y = sin(ang)) |&gt;
  select(id, label, x, y, sent)

# crisis-day directed private edges (ALL broadcasts excluded), reusing the explicit role_map
net_edges &lt;- messages |&gt; filter(phase == "crisis") |&gt;
  transmute(from = agent_id, channel, recipients) |&gt;
  separate_rows(recipients, sep = "; ") |&gt;
  filter(recipients != "", recipients != "ALL") |&gt;
  left_join(role_map, by = "recipients") |&gt;
  filter(!is.na(to), to != from) |&gt;
  group_by(from, to) |&gt;
  summarise(n = n(), n_off = sum(channel == "side_huddle"), .groups = "drop") |&gt;
  mutate(type = if_else(n_off &gt;= n/2, "off-record", "other"))

# ojs_define() is injected by Quarto only at render time; stub it when the chunk is run
# interactively (e.g. RStudio "Run Chunk") so this code doesn't error outside a render.
if (!isTRUE(getOption("knitr.in.progress"))) ojs_define &lt;- function(...) invisible(NULL)
ojs_define(ojs_nodes = net_nodes)
ojs_define(ojs_edges = net_edges)




OJS data bridge
nodes = transpose(ojs_nodes)
edges = transpose(ojs_edges)
labelOf = new Map(nodes.map(d =&gt; [d.id, d.label]))

























Agent filter control
viewof focus = Inputs.radio(["All"].concat(nodes.map(d =&gt; d.id)), {
  label: "Isolate agent:", value: "All",
  format: id =&gt; id === "All" ? "All" : labelOf.get(id)
})









Ego-network filter
neighbors = {
  if (focus === "All") return new Set(nodes.map(d =&gt; d.id));
  const s = new Set([focus]);
  for (const e of edges) { if (e.from === focus) s.add(e.to); if (e.to === focus) s.add(e.from); }
  return s;
}









Network chart code
netChart = {
  const d3 = await require("d3@7");
  const W = 760, H = 640, cx = W/2, cy = 360, R = 200;
  const pos = new Map(nodes.map(d =&gt; [d.id, d]));
  const px = d =&gt; cx + d.x * R, py = d =&gt; cy - d.y * R;
  const rs = d3.scaleSqrt().domain([0, d3.max(nodes, d =&gt; d.sent)]).range([4, 34]);
  const ws = d3.scaleLinear().domain([1, d3.max(edges, e =&gt; e.n)]).range([1, 7]);
  const col = {"off-record": "#F59E0B", "other": "#38BDF8"};
  const textPrimary = "#E5E7EB", textMuted = "#94A3B8";
  const nodeFill = "#60A5FA", focusStroke = "#F8FAFC", strokeMuted = "#1E293B";
  const edgeActive = e =&gt; focus === "All" || e.from === focus || e.to === focus;
  const nodeActive = d =&gt; neighbors.has(d.id);
  const nodeRadius = id =&gt; rs(pos.get(id).sent);
  const edgePoint = e =&gt; {
    const a = pos.get(e.from), b = pos.get(e.to);
    const x1 = px(a), y1 = py(a), x2 = px(b), y2 = py(b);
    const dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy) || 1;
    const sourcePad = nodeRadius(e.from) + 3;
    const targetPad = nodeRadius(e.to) + 9;
    return {
      x1: x1 + dx / len * sourcePad,
      y1: y1 + dy / len * sourcePad,
      x2: x2 - dx / len * targetPad,
      y2: y2 - dy / len * targetPad
    };
  };

  const svg = d3.create("svg")
    .attr("viewBox", [0, 0, W, H]).attr("width", W).attr("height", H)
    .attr("role", "img")
    .attr("aria-label", "Directed crisis-day private message network")
    .style("max-width", "100%").style("height", "auto").style("font", "13px sans-serif");

  const defs = svg.append("defs");
  for (const [type, color] of Object.entries(col)) {
    defs.append("marker")
      .attr("id", `arrow-${type}`)
      .attr("viewBox", "0 -5 10 10")
      .attr("refX", 9).attr("refY", 0)
      .attr("markerWidth", 6).attr("markerHeight", 6)
      .attr("orient", "auto")
      .attr("markerUnits", "strokeWidth")
      .append("path")
      .attr("d", "M0,-5L10,0L0,5")
      .attr("fill", color);
  }

  svg.append("g").selectAll("line").data(edges).join("line")
    .attr("x1", e =&gt; edgePoint(e).x1).attr("y1", e =&gt; edgePoint(e).y1)
    .attr("x2", e =&gt; edgePoint(e).x2).attr("y2", e =&gt; edgePoint(e).y2)
    .attr("stroke", e =&gt; col[e.type]).attr("stroke-width", e =&gt; ws(e.n))
    .attr("stroke-linecap", "round")
    .attr("stroke-opacity", e =&gt; edgeActive(e) ? 0.86 : 0.16)
    .attr("marker-end", e =&gt; `url(#arrow-${e.type})`);

  svg.append("g").selectAll("circle").data(nodes).join("circle")
    .attr("cx", d =&gt; px(d)).attr("cy", d =&gt; py(d)).attr("r", d =&gt; rs(d.sent))
    .attr("fill", nodeFill).attr("fill-opacity", d =&gt; nodeActive(d) ? 0.96 : 0.24)
    .attr("stroke", d =&gt; d.id === focus ? focusStroke : strokeMuted)
    .attr("stroke-width", d =&gt; d.id === focus ? 2.8 : 1.2)
    .append("title").text(d =&gt; `${d.label}: ${d.sent} messages sent`);

  svg.append("g").selectAll("text").data(nodes).join("text")
    .attr("x", d =&gt; cx + d.x * (R + 28)).attr("y", d =&gt; cy - d.y * (R + 28))
    .attr("text-anchor", "middle").attr("dy", "0.35em")
    .attr("font-weight", d =&gt; nodeActive(d) ? 600 : 400)
    .attr("fill", d =&gt; nodeActive(d) ? textPrimary : textMuted)
    .attr("fill-opacity", d =&gt; nodeActive(d) ? 1 : 0.68)
    .attr("stroke", "#0F172A")
    .attr("stroke-width", 3)
    .attr("stroke-linejoin", "round")
    .attr("paint-order", "stroke")
    .text(d =&gt; d.label);

  const legend = svg.append("g")
    .attr("transform", "translate(24,22)")
    .style("pointer-events", "none");
  legend.append("rect")
    .attr("width", 274).attr("height", 150).attr("rx", 6)
    .attr("fill", "#0F172A").attr("fill-opacity", 0.82)
    .attr("stroke", "#334155").attr("stroke-width", 1);
  legend.append("text")
    .attr("x", 14).attr("y", 22)
    .attr("fill", textPrimary).attr("font-weight", 700)
    .text("Legend");

  const lineLegend = [
    {y: 44, color: col["off-record"], width: 3, marker: "url(#arrow-off-record)", label: "off-record side_huddle"},
    {y: 68, color: col["other"], width: 3, marker: "url(#arrow-other)", label: "other internal message"},
    {y: 92, color: textMuted, width: 7, marker: null, label: "thicker line = more messages"}
  ];
  legend.selectAll("line.legend-edge").data(lineLegend).join("line")
    .attr("class", "legend-edge")
    .attr("x1", 16).attr("x2", 62).attr("y1", d =&gt; d.y).attr("y2", d =&gt; d.y)
    .attr("stroke", d =&gt; d.color).attr("stroke-width", d =&gt; d.width)
    .attr("stroke-linecap", "round")
    .attr("marker-end", d =&gt; d.marker);
  legend.selectAll("text.legend-edge-label").data(lineLegend).join("text")
    .attr("class", "legend-edge-label")
    .attr("x", 76).attr("y", d =&gt; d.y + 4)
    .attr("fill", textPrimary).attr("font-size", 12)
    .text(d =&gt; d.label);

  legend.append("circle")
    .attr("cx", 39).attr("cy", 120).attr("r", 11)
    .attr("fill", nodeFill).attr("fill-opacity", 0.96)
    .attr("stroke", strokeMuted).attr("stroke-width", 1.2);
  legend.append("text")
    .attr("x", 76).attr("y", 124)
    .attr("fill", textPrimary).attr("font-size", 12)
    .text("larger circle = more messages sent");
  legend.append("text")
    .attr("x", 16).attr("y", 142)
    .attr("fill", textMuted).attr("font-size", 11)
    .text("arrowhead shows message direction");

  return svg.node();
}













